{"code":"import os, glob

home = os.path.expanduser("~")
hits = []
for root in [home, os.path.join(home, ".hermes")]:
    for dirpath, dirs, files in os.walk(root):
        dirs[:] = [d for d in dirs if d not in (".git", "node_modules", ".cache")]
        if dirpath.count(os.sep) - root.count(os.sep) > 4:
            dirs[:] = []
            continue
        for f in files:
            if f in ("PENDENTES.md", "MAPA.md", "SOUL.md"):
                hits.append(os.path.join(dirpath, f))
print("arquivos de serviço:", "\n".join(hits) if hits else "— nenhum")

# skills alvo instaladas?
targets = ["skill-creator", "agent-context-kit", "conselho-de-ia"]
sd = os.path.join(home, ".hermes", "skills")
have = sorted({os.path.basename(os.path.dirname(p)) for p in glob.glob(os.path.join(sd, "*", "SKILL.md"))})
print("categorias de skills no default:", have)
print("alvos presentes:", {t: any(t in p for p in glob.glob(os.path.join(sd, "**", "SKILL.md"), recursive=True) + glob.glob(os.path.join(sd, "*", t, "SKILL.md"))) for t in targets})"}
